/* Instagram DNA — gallery white, hairline borders, gradient pink to purple */
.theme-instagram-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.985 0 0);
  --fg: oklch(0.269 0 0);
  --fg-muted: oklch(0.647 0 0);
  --accent: oklch(0.655 0.177 248.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.504 0.188 308.6);
  --line: oklch(0.891 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.810 0.148 71.1);
  --danger: oklch(0.641 0.200 20.5);
  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 2px color-mix(in oklab, oklch(0.6 0.2 350) 50%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Sen", sans-serif;
  --font-body: "Sen", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-instagram-dna h1,
.theme-instagram-dna h2,
.theme-instagram-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-instagram-dna h1 { background: linear-gradient(45deg, #f9ce34, #ee2a7b 50%, #6228d7); -webkit-background-clip: text; background-clip: text; color: transparent; }
.theme-instagram-dna h2 { color: #e1306c; }

/* depth */
.theme-instagram-dna thead th { font-size: 0.75em; text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-instagram-dna td { border-bottom: 1px solid var(--line); }
.theme-instagram-dna tbody tr:hover { background: var(--surface-2); }
.theme-instagram-dna a { color: oklch(0.42 0.11 250); font-weight: 600; text-decoration: none; }
.theme-instagram-dna a:hover { color: oklch(0.32 0.11 250); }
.theme-instagram-dna input, .theme-instagram-dna textarea, .theme-instagram-dna select { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); }
.theme-instagram-dna input:focus-visible, .theme-instagram-dna textarea:focus-visible, .theme-instagram-dna select:focus-visible { outline: none; border-color: oklch(0.65 0 0); box-shadow: var(--glow); }
.theme-instagram-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface-2); border: 1px solid var(--line); border-radius: 0.3rem; padding: 0.1em 0.45em; }
.theme-instagram-dna ::selection { background: oklch(0.9 0.06 350); }
.theme-instagram-dna ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-instagram-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-instagram-dna ::-webkit-scrollbar-thumb { background: oklch(0.8 0 0); border-radius: 4px; }
.theme-instagram-dna .label-caps { background: linear-gradient(45deg, #ee2a7b, #6228d7); -webkit-background-clip: text; background-clip: text; color: transparent; font-weight: 700; }
.theme-instagram-dna div.themed-border { border: 2px solid transparent; background: linear-gradient(var(--surface), var(--surface)) padding-box, linear-gradient(45deg, #f9ce34, #ee2a7b, #6228d7) border-box; } /* story ring — div only: must not clobber chip/button fills */
.theme-instagram-dna button:active { transform: scale(0.96); } /* double-tap */

/* alt mode: Instagram dark — true black gallery, hairlines only */
.theme-instagram-dna.alt-mode {
  --bg: oklch(0.05 0 0);
  --surface: oklch(0.16 0 0);
  --surface-2: oklch(0.21 0 0);
  --fg: oklch(0.97 0 0);
  --fg-muted: oklch(0.68 0 0);
  --line: oklch(1 0 0 / 12%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-instagram-dna.alt-mode a { color: oklch(0.72 0.11 250); }
.theme-instagram-dna.alt-mode a:hover { color: oklch(0.80 0.10 250); }
.theme-instagram-dna.alt-mode .label-caps { background: linear-gradient(45deg, oklch(0.72 0.20 0), oklch(0.68 0.20 300)); -webkit-background-clip: text; background-clip: text; }
.theme-instagram-dna.alt-mode ::selection { background: oklch(0.45 0.10 350); }
.theme-instagram-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.4 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
